#!/usr/bin/env python3
"""Focused disposable-key verification on an authorized SSH test host.
Requires an existing pinned synthetic PostgreSQL fixture (postgres-result.json).
Creates only owned temporary GPG homes, fixture files and network-none PG container.
"""
import argparse, base64, json, subprocess
from pathlib import Path
TEMPLATE = '\nimport base64,hashlib,io,json,os,subprocess as sp,tempfile,time,tarfile,secrets,uuid\nfrom pathlib import Path\nos.umask(0o077)\nreport={\'scope\':\'disposable GPG keys and existing synthetic PostgreSQL fixture only\',\'production_data_accessed\':False,\'checks\':[]}\ndef run(a,**kw):\n p=sp.run(a,capture_output=True,**kw)\n if p.returncode: raise RuntimeError(\'Synthetic command failed: \'+str(a)+\' \'+p.stderr.decode(errors=\'replace\'))\n return p\ndef sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()\ncontainer=None\nwith tempfile.TemporaryDirectory(prefix=\'scec-gpg-test-\') as temp:\n root=Path(temp);tool=root/\'scec_recovery.py\';tool.write_bytes(base64.b64decode(TOOL))\n home=root/\'keys\';home.mkdir(mode=0o700)\n try:\n  run([\'gpg\',\'--homedir\',str(home),\'--batch\',\'--pinentry-mode\',\'loopback\',\'--passphrase\',\'\',\'--quick-generate-key\',\'SCEC DISPOSABLE SYNTHETIC TEST\',\'rsa2048\',\'encr\',\'1d\'])\n  rows=run([\'gpg\',\'--homedir\',str(home),\'--with-colons\',\'--list-keys\']).stdout.decode().splitlines();fpr=next(x.split(\':\')[9] for x in rows if x.startswith(\'fpr:\'))\n  source=Path(FIXTURE_ROOT);prior=json.loads((source/\'postgres-result.json\').read_text())\n  dumps=[x for x in source.glob(\'synthetic-postgres-fixture-*.dump\') if sha(x)==prior[\'checks\'][\'dump_sha256\']];assert len(dumps)==1\n  fixture=root/\'fixture.json\';fixture.write_text(json.dumps({\'synthetic\':True,\'tenant\':\'test-only\',\'values\':[1,2,3]}))\n  output=root/\'recovery.tar.gpg\';plan={\'mode\':\'synthetic\',\'label\':\'SYNTHETIC-GPG-RECOVERY\',\'gpg_home\':str(home),\'recipient\':fpr,\'output\':str(output),\'files\':[{\'name\':\'database.dump\',\'path\':str(dumps[0]),\'sha256\':sha(dumps[0])},{\'name\':\'fixture.json\',\'path\':str(fixture),\'sha256\':sha(fixture)}]};pp=root/\'plan.json\';pp.write_text(json.dumps(plan))\n  def invoke(args,success=True):\n   p=sp.run([\'python3\',str(tool)]+args,capture_output=True,text=True);assert (p.returncode==0)==success,(args,p.stdout,p.stderr);return json.loads(p.stdout)\n  def check(name,ok=True):assert ok,name;report[\'checks\'].append({\'name\':name,\'result\':\'PASS\'})\n  result=invoke([\'backup\',\'--plan\',str(pp)]);check(\'encrypt_bundle\');expected=result[\'ciphertext_sha256\'];report[\'bundle_bytes\']=result[\'ciphertext_bytes\'];report[\'synthetic_dump_sha256\']=sha(dumps[0])\n  target=root/\'restore\';args=[\'restore\',\'--bundle\',str(output),\'--sha256\',expected,\'--gpg-home\',str(home),\'--recipient\',fpr,\'--target\',str(target),\'--max-bytes\',\'16777216\']\n  restored=invoke(args);check(\'decrypt_and_verify_all_files\',sha(target/\'database.dump\')==sha(dumps[0]) and sha(target/\'fixture.json\')==sha(fixture));report[\'restored_files\']=restored[\'files_verified\']\n  invoke([\'backup\',\'--plan\',str(pp)],False);check(\'existing_output_refused\')\n  invoke(args,False);check(\'existing_restore_target_refused\')\n  badargs=args.copy();badargs[badargs.index(\'--sha256\')+1]=\'0\'*64;badargs[badargs.index(\'--target\')+1]=str(root/\'bad-hash\');invoke(badargs,False);check(\'ciphertext_checksum_mismatch_refused\')\n  original=json.loads(pp.read_text());bad=dict(original,output=str(root/\'drift.gpg\'));bad[\'files\']=[dict(original[\'files\'][0],sha256=\'0\'*64)];pp.write_text(json.dumps(bad));invoke([\'backup\',\'--plan\',str(pp)],False);check(\'source_drift_refused\',not (root/\'drift.gpg\').exists())\n  bad=dict(original,mode=\'production\',output=str(root/\'production.gpg\'));pp.write_text(json.dumps(bad));invoke([\'backup\',\'--plan\',str(pp)],False);check(\'production_without_approval_refused\',not (root/\'production.gpg\').exists())\n  bad=dict(original,recipient=\'A\'*40,output=str(root/\'missing.gpg\'));pp.write_text(json.dumps(bad));invoke([\'backup\',\'--plan\',str(pp)],False);check(\'missing_recipient_refused\',not (root/\'missing.gpg\').exists());pp.write_text(json.dumps(original))\n  # Corrupt ciphertext and independently recompute its hash: decryption integrity must still fail.\n  tamper=root/\'tampered.gpg\';b=bytearray(output.read_bytes());b[len(b)//2]^=1;tamper.write_bytes(b)\n  badargs=args.copy();badargs[badargs.index(\'--bundle\')+1]=str(tamper);badargs[badargs.index(\'--sha256\')+1]=sha(tamper);badargs[badargs.index(\'--target\')+1]=str(root/\'bad-integrity\');invoke(badargs,False);check(\'tampered_ciphertext_integrity_refused_and_cleanup\',not (root/\'bad-integrity\').exists())\n  badargs=args.copy();badargs[badargs.index(\'--target\')+1]=str(root/\'limit\');badargs[badargs.index(\'--max-bytes\')+1]=\'10\';invoke(badargs,False);check(\'restore_size_limit_and_cleanup\',not (root/\'limit\').exists())\n  # Authentically encrypted hostile archive, using the same disposable key.\n  hostile=root/\'hostile.tar\';\n  with tarfile.open(hostile,\'w\') as t:\n   i=tarfile.TarInfo(\'../escape\');i.size=1;t.addfile(i,io.BytesIO(b\'x\'))\n  enc=root/\'hostile.gpg\';run([\'gpg\',\'--homedir\',str(home),\'--batch\',\'--trust-model\',\'always\',\'--recipient\',fpr,\'--output\',str(enc),\'--encrypt\',str(hostile)])\n  badargs=args.copy();badargs[badargs.index(\'--bundle\')+1]=str(enc);badargs[badargs.index(\'--sha256\')+1]=sha(enc);badargs[badargs.index(\'--target\')+1]=str(root/\'hostile-out\');invoke(badargs,False);check(\'archive_traversal_refused_and_cleanup\',not (root/\'escape\').exists() and not (root/\'hostile-out\').exists())\n  # Re-encrypted payload with an incorrect manifest hash must fail content verification.\n  wrong=root/\'wrong.tar\'\n  with tarfile.open(wrong,\'w\') as t:\n   body=b\'synthetic\';manifest=json.dumps({\'format\':1,\'label\':\'SYNTHETIC-BAD-HASH\',\'files\':[{\'name\':\'item\',\'size\':len(body),\'sha256\':\'0\'*64}]}).encode()\n   for n,d in [(\'manifest.json\',manifest),(\'item\',body)]:\n    i=tarfile.TarInfo(n);i.size=len(d);t.addfile(i,io.BytesIO(d))\n  enc2=root/\'wrong.gpg\';run([\'gpg\',\'--homedir\',str(home),\'--batch\',\'--trust-model\',\'always\',\'--recipient\',fpr,\'--output\',str(enc2),\'--encrypt\',str(wrong)])\n  badargs=args.copy();badargs[badargs.index(\'--bundle\')+1]=str(enc2);badargs[badargs.index(\'--sha256\')+1]=sha(enc2);badargs[badargs.index(\'--target\')+1]=str(root/\'wrong-out\');invoke(badargs,False);check(\'restored_content_hash_mismatch_and_cleanup\',not (root/\'wrong-out\').exists())\n  # Focused new evidence: actual PostgreSQL restore from GPG-decrypted dump, not a repeated application suite.\n  container=\'scec-gpg-\'+uuid.uuid4().hex[:10];env=root/\'postgres.env\';env.write_text(\'POSTGRES_PASSWORD=\'+secrets.token_urlsafe(32)+\'\\nPOSTGRES_DB=scec_synthetic_recovery\\n\')\n  started=time.monotonic();run([\'docker\',\'run\',\'-d\',\'--name\',container,\'--network\',\'none\',\'--memory\',\'512m\',\'--cpus\',\'0.5\',\'--tmpfs\',\'/var/lib/postgresql/data:rw\',\'--env-file\',str(env),prior[\'postgres_image_id\']])\n  for _ in range(60):\n   if sp.run([\'docker\',\'exec\',container,\'pg_isready\',\'-h\',\'127.0.0.1\',\'-U\',\'postgres\'],stdout=sp.DEVNULL,stderr=sp.DEVNULL).returncode==0:break\n   time.sleep(1)\n  else:raise RuntimeError(\'isolated database readiness failed\')\n  run([\'docker\',\'exec\',\'-i\',container,\'pg_restore\',\'--exit-on-error\',\'--no-owner\',\'--no-acl\',\'-U\',\'postgres\',\'-d\',\'scec_synthetic_recovery\'],input=(target/\'database.dump\').read_bytes());check(\'postgres_restore_from_decrypted_dump\')\n  def sql(s):return run([\'docker\',\'exec\',\'-i\',container,\'psql\',\'-X\',\'-q\',\'-v\',\'ON_ERROR_STOP=1\',\'-U\',\'postgres\',\'-d\',\'scec_synthetic_recovery\',\'-At\'],input=s.encode()).stdout.decode().strip()\n  check(\'restored_revision_850_001\',sql(\'SELECT version_num FROM alembic_version\')==\'850_001\')\n  counts=json.loads(sql("SELECT json_object_agg(t, n) FROM (SELECT tablename t, (xpath(\'/row/c/text()\',query_to_xml(format(\'SELECT count(*) AS c FROM %I.%I\',schemaname,tablename),false,true,\'\')))[1]::text::bigint n FROM pg_tables WHERE schemaname=\'public\') x"));report[\'restored_table_counts\']=counts;check(\'restored_18_tables\',len(counts)==18);check(\'restored_fixture_counts_match_prior_evidence\',counts[\'contacts\']==prior[\'checks\'][\'restore_contact_count\'] and counts[\'organizations\']==2 and counts[\'alembic_version\']==1)\n  report[\'postgres_restore_seconds\']=round(time.monotonic()-started,3);report[\'postgres_image_id\']=prior[\'postgres_image_id\'];report[\'tool_sha256\']=sha(tool);report[\'result\']=\'PASS\'\n finally:\n  if container:report[\'owned_container_removed\']=sp.run([\'docker\',\'rm\',\'-f\',container],capture_output=True).returncode==0\n  sp.run([\'gpgconf\',\'--homedir\',str(home),\'--kill\',\'all\'],capture_output=True)\nreport[\'disposable_keys_and_plaintext_removed\']=not root.exists()\nprint(json.dumps(report))\n'

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--ssh-target',required=True);ap.add_argument('--identity',type=Path,required=True)
    ap.add_argument('--fixture-root',required=True);ap.add_argument('--evidence',type=Path,required=True);args=ap.parse_args()
    code=TEMPLATE.replace('TOOL',repr(base64.b64encode(Path(__file__).with_name('scec_recovery.py').read_bytes()).decode())).replace('FIXTURE_ROOT',repr(args.fixture_root))
    p=subprocess.run(['ssh','-i',str(args.identity),'-o','IdentitiesOnly=yes','-o','BatchMode=yes',args.ssh_target,'python3 -'],input=code,text=True,capture_output=True)
    if p.returncode:
        print(p.stderr);raise SystemExit(p.returncode)
    result=json.loads(p.stdout);args.evidence.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))

if __name__=='__main__':main()
